using System.Collections.Frozen;
using System.Globalization;
using System.Text;
using AngleSharp.Dom;

namespace BlazorAccessibilityToolkit.ComponentTesting.Internal;

/// <summary>
/// Roles (WAI-ARIA 1.2 and HTML-AAM), accessible names and descriptions (accname 1.2) computed on bUnit's rendered
/// markup. There is no CSS: an element is hidden when it, or an ancestor, has <c>hidden</c>, <c>inert</c>,
/// <c>aria-hidden="true"</c> or an inline <c>display: none</c> / <c>visibility: hidden</c> style, and block-level
/// elements are recognized by tag name. Content generated by CSS (<c>::before</c>) is not part of names.
/// </summary>
internal sealed class AccessibilityComputation
{
    private static readonly FrozenSet<string> ValidRoles = FrozenSet.ToFrozenSet(
    [
        "alert", "alertdialog", "application", "article", "banner", "blockquote", "button", "caption", "cell", "checkbox", "code", "columnheader",
        "combobox", "comment", "complementary", "contentinfo", "definition", "deletion", "dialog", "directory", "document", "emphasis", "feed", "figure", "form",
        "generic", "grid", "gridcell", "group", "heading", "img", "insertion", "link", "list", "listbox", "listitem", "log", "main", "mark",
        "marquee", "math", "menu", "menubar", "menuitem", "menuitemcheckbox", "menuitemradio", "meter", "navigation", "none", "note", "option",
        "paragraph", "presentation", "progressbar", "radio", "radiogroup", "region", "row", "rowgroup", "rowheader", "scrollbar", "search", "searchbox",
        "sectionfooter", "sectionheader", "separator", "slider", "spinbutton", "status", "strong", "subscript", "suggestion", "superscript", "switch",
        "tab", "table", "tablist", "tabpanel", "term", "textbox", "time", "timer", "toolbar", "tooltip", "tree", "treegrid", "treeitem",
    ], StringComparer.Ordinal);

    // Roles that take their name from their content (accname 1.2, "name from: contents").
    private static readonly FrozenSet<string> NameFromContent = FrozenSet.ToFrozenSet(
    [
        "button", "cell", "checkbox", "columnheader", "gridcell", "heading", "link", "menuitem", "menuitemcheckbox", "menuitemradio", "option",
        "radio", "row", "rowheader", "sectionfooter", "sectionheader", "switch", "tab", "tooltip", "treeitem", "comment", "suggestion",
    ], StringComparer.Ordinal);

    private static readonly FrozenSet<string> GlobalAria = FrozenSet.ToFrozenSet(
    [
        "aria-atomic", "aria-busy", "aria-controls", "aria-current", "aria-describedby", "aria-description", "aria-details", "aria-dropeffect",
        "aria-flowto", "aria-grabbed", "aria-haspopup", "aria-keyshortcuts", "aria-label", "aria-labelledby", "aria-live", "aria-owns", "aria-relevant",
        "aria-roledescription",
    ], StringComparer.Ordinal);

    private static readonly FrozenSet<string> BlockElements = FrozenSet.ToFrozenSet(
    [
        "address", "article", "aside", "blockquote", "br", "dd", "details", "dialog", "div", "dl", "dt", "fieldset", "figcaption", "figure", "footer",
        "form", "h1", "h2", "h3", "h4", "h5", "h6", "header", "hr", "li", "main", "nav", "ol", "p", "pre", "section", "summary", "table", "td", "th",
        "tr", "ul", "caption", "legend", "option", "select",
    ], StringComparer.Ordinal);

    private readonly Dictionary<string, IElement> _byId = new(StringComparer.Ordinal);
    private readonly List<IElement> _elements = [];
    private IElement? _referenceRoot;

    public AccessibilityComputation(IEnumerable<INode> roots)
    {
        foreach (var root in roots)
        {
            Collect(root);
        }
    }

    /// <summary>All elements in document order.</summary>
    public IReadOnlyList<IElement> Elements => _elements;

    /// <summary>Creates a computation for the tree that contains <paramref name="element"/>.</summary>
    public static AccessibilityComputation For(IElement element)
    {
        INode top = element;
        while (top.Parent is { } parent)
        {
            top = parent;
        }

        return new AccessibilityComputation([top]);
    }

    public IElement? ById(string id) => _byId.GetValueOrDefault(id);

    /// <summary>The computed role: the first valid explicit role, otherwise the implicit role, or <c>null</c> (generic).</summary>
    public string? Role(IElement element)
    {
        foreach (var token in Tokens(element.GetAttribute("role")))
        {
            var role = token.ToLowerInvariant();
            if (role == "image")
            {
                role = "img";
            }

            if (!ValidRoles.Contains(role))
            {
                continue;
            }

            // Presentational roles are ignored on focusable elements and elements with global ARIA attributes.
            if (role is "none" or "presentation" && (IsFocusable(element) || element.Attributes.Any(a => GlobalAria.Contains(a.Name))))
            {
                return ImplicitRole(element);
            }

            return role == "presentation" ? "none" : role;
        }

        return ImplicitRole(element);
    }

    /// <summary>The implicit role of the element (HTML-AAM), or <c>null</c>.</summary>
    public string? ImplicitRole(IElement element)
    {
        string Type() => (element.GetAttribute("type") ?? "text").Trim().ToLowerInvariant();
        bool Named() => !string.IsNullOrWhiteSpace(element.GetAttribute("aria-label")) || Tokens(element.GetAttribute("aria-labelledby")).Any(id => _byId.ContainsKey(id)) || !string.IsNullOrWhiteSpace(element.GetAttribute("title"));
        bool InSection() => element.Ancestors<IElement>().Any(a => a.LocalName is "article" or "aside" or "main" or "nav" or "section");

        return element.LocalName switch
        {
            "a" or "area" => element.HasAttribute("href") ? "link" : null,
            "article" => "article",
            "aside" => "complementary",
            "blockquote" => "blockquote",
            "button" => "button",
            "caption" => "caption",
            "code" => "code",
            "datalist" => "listbox",
            "dd" => "definition",
            "del" or "s" => "deletion",
            "details" => "group",
            "dfn" or "dt" => "term",
            "dialog" => "dialog",
            "em" => "emphasis",
            "fieldset" or "optgroup" => "group",
            "figure" => "figure",
            "footer" => InSection() ? null : "contentinfo",
            "form" => Named() ? "form" : null,
            "h1" or "h2" or "h3" or "h4" or "h5" or "h6" => "heading",
            "header" => InSection() ? null : "banner",
            "hr" => "separator",
            "img" => element.GetAttribute("alt") is { Length: 0 } && !Named() ? "none" : "img",
            "input" => Type() switch
            {
                "button" or "submit" or "reset" or "image" => "button",
                "checkbox" => "checkbox",
                "radio" => "radio",
                "range" => "slider",
                "number" => "spinbutton",
                "search" => element.HasAttribute("list") ? "combobox" : "searchbox",
                "email" or "tel" or "text" or "url" => element.HasAttribute("list") ? "combobox" : "textbox",
                "hidden" or "password" or "color" or "date" or "datetime-local" or "month" or "time" or "week" or "file" => null,
                _ => "textbox",
            },
            "ins" => "insertion",
            "li" => "listitem",
            "main" => "main",
            "mark" => "mark",
            "menu" or "ol" or "ul" => "list",
            "meter" => "meter",
            "nav" => "navigation",
            "option" => "option",
            "output" => "status",
            "p" => "paragraph",
            "progress" => "progressbar",
            "search" => "search",
            "section" => Named() ? "region" : null,
            "select" => element.HasAttribute("multiple") || (int.TryParse(element.GetAttribute("size"), NumberStyles.Integer, CultureInfo.InvariantCulture, out var size) && size > 1) ? "listbox" : "combobox",
            "strong" or "b" => "strong",
            "sub" => "subscript",
            "sup" => "superscript",
            "table" => "table",
            "tbody" or "thead" or "tfoot" => "rowgroup",
            "td" => element.Ancestors<IElement>().FirstOrDefault(a => a.LocalName == "table") is { } table && Role(table) is "grid" or "treegrid" ? "gridcell" : "cell",
            "th" => HeaderRole(element),
            "textarea" => "textbox",
            "time" => "time",
            "tr" => "row",
            _ => null,
        };
    }

    /// <summary>True when the element is excluded from the accessibility tree.</summary>
    public static bool IsHidden(IElement element) => IsHidden(element, null);

    // Hidden below (not including) stopAt: content of an element referenced by aria-labelledby is used even when the
    // referenced element itself is hidden.
    private static bool IsHidden(IElement element, IElement? stopAt)
    {
        // visibility is inherited, but a descendant can make itself visible again: the nearest declaration decides.
        for (var current = element; current is not null && current != stopAt; current = current.ParentElement)
        {
            if (InlineStyle(current, "visibility") is { } visibility)
            {
                if (visibility is "hidden" or "collapse")
                {
                    return true;
                }

                break;
            }
        }

        for (var current = element; current is not null && current != stopAt; current = current.ParentElement)
        {
            if (current.HasAttribute("hidden") || current.HasAttribute("inert") || string.Equals(current.GetAttribute("aria-hidden")?.Trim(), "true", StringComparison.OrdinalIgnoreCase)
                || current.LocalName is "template" or "script" or "style" or "noscript"
                || (current.LocalName == "input" && string.Equals(current.GetAttribute("type"), "hidden", StringComparison.OrdinalIgnoreCase))
                || DisplayNone(current))
            {
                return true;
            }

            // Closed <details>: only the summary is rendered.
            if (current.ParentElement is { LocalName: "details" } details && !details.HasAttribute("open") && current.LocalName != "summary")
            {
                return true;
            }
        }

        return false;
    }

    public static bool IsFocusable(IElement element)
    {
        if (element.HasAttribute("disabled") && element.LocalName is "button" or "input" or "select" or "textarea" or "fieldset")
        {
            return false;
        }

        if (element.GetAttribute("tabindex") is { } tabIndex && int.TryParse(tabIndex.Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out _))
        {
            return true;
        }

        return element.LocalName switch
        {
            "a" or "area" => element.HasAttribute("href"),
            "button" or "select" or "textarea" or "iframe" or "summary" => true,
            "input" => !string.Equals(element.GetAttribute("type"), "hidden", StringComparison.OrdinalIgnoreCase),
            "audio" or "video" => element.HasAttribute("controls"),
            _ => element.GetAttribute("contenteditable") is { } editable && !string.Equals(editable, "false", StringComparison.OrdinalIgnoreCase),
        };
    }

    /// <summary>The accessible name (accname 1.2 subset, whitespace normalized).</summary>
    public string Name(IElement element)
    {
        // The name of a hidden element (queried with Hidden = true) is computed as if it were shown.
        var previous = _referenceRoot;
        _referenceRoot = IsHidden(element) ? element : null;
        try
        {
            return Normalize(TextAlternative(element, new HashSet<IElement>(), inLabelledBy: false, inChildTraversal: false, inLabel: false));
        }
        finally
        {
            _referenceRoot = previous;
        }
    }

    /// <summary>The accessible description: aria-describedby, aria-description, or a title not used for the name.</summary>
    public string Description(IElement element)
    {
        var ids = Tokens(element.GetAttribute("aria-describedby")).Select(ById).Where(e => e is not null).ToArray();
        if (ids.Length > 0)
        {
            return Normalize(string.Join(" ", ids.Select(e => Referenced(e!, new HashSet<IElement>()))));
        }

        if (element.GetAttribute("aria-description") is { } description && !string.IsNullOrWhiteSpace(description))
        {
            return Normalize(description);
        }

        var title = Normalize(element.GetAttribute("title"));
        return title.Length > 0 && Name(element) != title ? title : string.Empty;
    }

    /// <summary>The error message: the text of the aria-errormessage targets, only while the element is invalid.</summary>
    public string ErrorMessage(IElement element)
    {
        if (!IsInvalid(element))
        {
            return string.Empty;
        }

        var targets = Tokens(element.GetAttribute("aria-errormessage")).Select(ById).Where(e => e is not null).ToArray();
        return Normalize(string.Join(" ", targets.Select(e => Referenced(e!, new HashSet<IElement>()))));
    }

    public static bool IsInvalid(IElement element) =>
        element.GetAttribute("aria-invalid") is { } invalid && invalid.Trim().Length > 0 && !string.Equals(invalid.Trim(), "false", StringComparison.OrdinalIgnoreCase);

    /// <summary>A state value without the <c>aria-</c> prefix, combining ARIA attributes and native semantics.</summary>
    public string? State(IElement element, string state, string? role = null)
    {
        role ??= Role(element);
        switch (state)
        {
            case "checked":
                if (element.LocalName == "input" && (element.GetAttribute("type") ?? string.Empty).ToLowerInvariant() is "checkbox" or "radio")
                {
                    return element.HasAttribute("indeterminate") ? "mixed" : element.HasAttribute("checked") ? "true" : "false";
                }

                return role is "checkbox" or "radio" or "switch" or "menuitemcheckbox" or "menuitemradio" ? Lower(element.GetAttribute("aria-checked")) ?? "false" : Lower(element.GetAttribute("aria-checked"));
            case "selected":
                if (element.LocalName == "option")
                {
                    return element.HasAttribute("selected") || string.Equals(element.GetAttribute("aria-selected"), "true", StringComparison.OrdinalIgnoreCase) ? "true" : "false";
                }

                return Lower(element.GetAttribute("aria-selected"));
            case "disabled":
                var disabled = (element.HasAttribute("disabled") && element.LocalName is "button" or "input" or "select" or "textarea" or "fieldset" or "optgroup" or "option")
                    || element.Ancestors<IElement>().Any(a => a.LocalName == "fieldset" && a.HasAttribute("disabled") && !IsInFirstLegend(element, a))
                    || new[] { element }.Concat(element.Ancestors<IElement>()).Any(a => string.Equals(a.GetAttribute("aria-disabled"), "true", StringComparison.OrdinalIgnoreCase));
                return disabled ? "true" : null;
            case "required":
                return element.HasAttribute("required") || string.Equals(element.GetAttribute("aria-required"), "true", StringComparison.OrdinalIgnoreCase) ? "true" : null;
            case "readonly":
                return element.HasAttribute("readonly") || string.Equals(element.GetAttribute("aria-readonly"), "true", StringComparison.OrdinalIgnoreCase) ? "true" : null;
            case "invalid":
                return IsInvalid(element) ? Lower(element.GetAttribute("aria-invalid")) : null;
            case "level":
                if (element.GetAttribute("aria-level") is { } level && int.TryParse(level, NumberStyles.Integer, CultureInfo.InvariantCulture, out _))
                {
                    return level.Trim();
                }

                return element.LocalName is ['h', >= '1' and <= '6'] ? element.LocalName[1..] : role == "heading" ? "2" : null;
            case "current":
                return element.GetAttribute("aria-current") is { } current && current.Trim().Length > 0 && !string.Equals(current.Trim(), "false", StringComparison.OrdinalIgnoreCase) ? current.Trim().ToLowerInvariant() : null;
            case "valuenow":
                return element.GetAttribute("aria-valuenow") ?? (element.LocalName is "input" or "progress" or "meter" ? element.GetAttribute("value") : null);
            case "valuemin":
                return element.GetAttribute("aria-valuemin") ?? (element.LocalName is "input" or "meter" ? element.GetAttribute("min") : null);
            case "valuemax":
                return element.GetAttribute("aria-valuemax") ?? (element.LocalName is "input" or "progress" or "meter" ? element.GetAttribute("max") : null);
            case "valuetext" or "label" or "roledescription" or "keyshortcuts" or "placeholder":
                return element.GetAttribute("aria-" + state)?.Trim();
            default:
                return Lower(element.GetAttribute("aria-" + state));
        }
    }

    private static bool IsInFirstLegend(IElement element, IElement fieldset) =>
        fieldset.Children.FirstOrDefault(c => c.LocalName == "legend") is { } legend && legend.Contains(element);

    private string HeaderRole(IElement th)
    {
        var scope = th.GetAttribute("scope")?.Trim().ToLowerInvariant();
        if (scope is "row" or "rowgroup")
        {
            return "rowheader";
        }

        if (scope is "col" or "colgroup")
        {
            return "columnheader";
        }

        // A header cell in a body row after other cells, or the first cell of a body row with data cells, is a row header.
        var row = th.ParentElement;
        if (row?.ParentElement is { LocalName: "tbody" } && row.Children.Any(c => c.LocalName == "td"))
        {
            return "rowheader";
        }

        return "columnheader";
    }

    private string TextAlternative(IElement element, HashSet<IElement> visited, bool inLabelledBy, bool inChildTraversal, bool inLabel)
    {
        if (!visited.Add(element))
        {
            return string.Empty;
        }

        // 2A: hidden content is skipped, unless it was directly referenced by aria-labelledby.
        if (!inLabelledBy && IsHidden(element, _referenceRoot))
        {
            return string.Empty;
        }

        var role = Role(element);

        // 2B: aria-labelledby (not followed recursively).
        if (!inLabelledBy)
        {
            var targets = Tokens(element.GetAttribute("aria-labelledby")).Select(ById).Where(e => e is not null).ToArray();
            if (targets.Length > 0)
            {
                // An element may reference itself (aria-labelledby="self other"): its own text alternative is used.
                return string.Join(" ", targets.Select(t => t == element ? SelfReferenced(element, visited) : Referenced(t!, visited)).Where(s => s.Length > 0));
            }
        }

        // 2C: an embedded control inside a label or another element's content contributes its value.
        if ((inChildTraversal || inLabel) && EmbeddedValue(element, role) is { } value)
        {
            return value;
        }

        // 2D: aria-label.
        if (element.GetAttribute("aria-label") is { } label && !string.IsNullOrWhiteSpace(label))
        {
            return label.Trim();
        }

        // 2E: native text alternatives (HTML-AAM).
        if (role != "none" && NativeName(element, visited) is { Length: > 0 } native)
        {
            return native;
        }

        if (role == "none" && element.LocalName == "img")
        {
            return string.Empty;
        }

        // 2F: name from content.
        if (inChildTraversal || inLabelledBy || inLabel || (role is not null && NameFromContent.Contains(role)))
        {
            var content = Content(element, visited);
            if (content.Trim().Length > 0)
            {
                return content;
            }
        }

        // 2I: tooltip attribute, then placeholder for text fields.
        if (element.GetAttribute("title") is { } title && !string.IsNullOrWhiteSpace(title))
        {
            return title.Trim();
        }

        if (element.LocalName is "input" or "textarea" && element.GetAttribute("placeholder") is { } placeholder && !string.IsNullOrWhiteSpace(placeholder))
        {
            return placeholder.Trim();
        }

        return string.Empty;
    }

    // The text alternative of an element referenced by aria-labelledby, aria-describedby or aria-errormessage.
    private string Referenced(IElement target, HashSet<IElement> visited)
    {
        var previous = _referenceRoot;
        _referenceRoot = IsHidden(target) ? target : null;
        try
        {
            return TextAlternative(target, visited, inLabelledBy: true, inChildTraversal: false, inLabel: false);
        }
        finally
        {
            _referenceRoot = previous;
        }
    }

    private string SelfReferenced(IElement element, HashSet<IElement> visited)
    {
        visited.Remove(element);
        return TextAlternative(element, visited, inLabelledBy: true, inChildTraversal: false, inLabel: false);
    }

    private string? EmbeddedValue(IElement element, string? role)
    {
        switch (role)
        {
            case "textbox" or "searchbox":
                return element.LocalName == "textarea" ? element.TextContent : element.GetAttribute("value") ?? element.TextContent;
            case "combobox" or "listbox":
                if (element.LocalName == "select")
                {
                    var options = element.QuerySelectorAll("option").ToArray();
                    var selected = options.Where(o => o.HasAttribute("selected")).ToArray();
                    return Normalize((selected.Length > 0 ? selected : options.Take(1)).Select(o => o.TextContent).FirstOrDefault());
                }

                if (element.LocalName == "input")
                {
                    return element.GetAttribute("value") ?? string.Empty;
                }

                return Normalize(string.Join(" ", element.QuerySelectorAll("[aria-selected=true]").Select(o => o.TextContent)));
            case "slider" or "spinbutton" or "scrollbar" or "progressbar" or "meter":
                return element.GetAttribute("aria-valuetext") ?? element.GetAttribute("aria-valuenow") ?? element.GetAttribute("value") ?? string.Empty;
            default:
                return null;
        }
    }

    private string? NativeName(IElement element, HashSet<IElement> visited)
    {
        switch (element.LocalName)
        {
            case "input":
                var type = (element.GetAttribute("type") ?? "text").Trim().ToLowerInvariant();
                if (type is "button" or "submit" or "reset")
                {
                    return element.GetAttribute("value") is { } v && v.Trim().Length > 0 ? v : type switch { "submit" => "Submit", "reset" => "Reset", _ => LabelsName(element, visited) };
                }

                if (type == "image")
                {
                    return LabelsName(element, visited) is { Length: > 0 } labelled ? labelled : element.GetAttribute("alt") ?? element.GetAttribute("value") ?? "Submit";
                }

                return LabelsName(element, visited);
            case "select" or "textarea" or "meter" or "progress" or "output":
                return LabelsName(element, visited);
            case "button":
                return LabelsName(element, visited) is { Length: > 0 } buttonLabel ? buttonLabel : null;
            case "img" or "area":
                return element.GetAttribute("alt");
            case "fieldset":
                return element.Children.FirstOrDefault(c => c.LocalName == "legend") is { } legend ? Content(legend, visited) : null;
            case "figure":
                return element.Children.FirstOrDefault(c => c.LocalName == "figcaption") is { } caption ? Content(caption, visited) : null;
            case "table":
                return element.Children.FirstOrDefault(c => c.LocalName == "caption") is { } tableCaption ? Content(tableCaption, visited) : null;
            case "optgroup":
                return element.GetAttribute("label");
            case "svg":
                return element.Children.FirstOrDefault(c => c.LocalName == "title") is { } svgTitle ? svgTitle.TextContent : null;
            case "details":
                return null;
            default:
                return null;
        }
    }

    // Text of the <label> elements of a labelable control (wrapping label and label[for]).
    private string LabelsName(IElement control, HashSet<IElement> visited)
    {
        var labels = new List<IElement>();
        // A label without "for" labels its first labelable descendant.
        if (control.Ancestors<IElement>().FirstOrDefault(a => a.LocalName == "label") is { } wrapping
            && (wrapping.GetAttribute("for") is { } target ? target == control.Id : wrapping.QuerySelector("button, input:not([type=hidden]), meter, output, progress, select, textarea") == control))
        {
            labels.Add(wrapping);
        }

        if (!string.IsNullOrEmpty(control.Id))
        {
            labels.AddRange(_elements.Where(e => e.LocalName == "label" && e.GetAttribute("for") == control.Id && !labels.Contains(e)));
        }

        var parts = new List<string>();
        foreach (var label in labels)
        {
            if (IsHidden(label))
            {
                continue;
            }

            // The control itself is skipped in its label's content; other embedded controls contribute their values.
            var inner = new HashSet<IElement>(visited) { control };
            parts.Add(ContentForLabel(label, inner));
        }

        return Normalize(string.Join(" ", parts));
    }

    private string ContentForLabel(IElement label, HashSet<IElement> visited)
    {
        var sb = new StringBuilder();
        foreach (var child in label.ChildNodes)
        {
            AppendNode(child, sb, visited, inLabel: true);
        }

        return sb.ToString();
    }

    private string Content(IElement element, HashSet<IElement> visited)
    {
        var sb = new StringBuilder();
        foreach (var child in element.ChildNodes)
        {
            AppendNode(child, sb, visited, inLabel: false);
        }

        return sb.ToString();
    }

    private void AppendNode(INode node, StringBuilder sb, HashSet<IElement> visited, bool inLabel)
    {
        if (node.NodeType == NodeType.Text)
        {
            sb.Append(node.TextContent);
            return;
        }

        if (node is not IElement child || visited.Contains(child))
        {
            return;
        }

        var block = BlockElements.Contains(child.LocalName);
        if (block)
        {
            sb.Append(' ');
        }

        sb.Append(TextAlternative(child, visited, inLabelledBy: false, inChildTraversal: true, inLabel: inLabel));
        if (block)
        {
            sb.Append(' ');
        }
    }

    private void Collect(INode node)
    {
        if (node is IElement element)
        {
            _elements.Add(element);
            if (!string.IsNullOrEmpty(element.Id))
            {
                _byId.TryAdd(element.Id, element);
            }
        }

        foreach (var child in node.ChildNodes)
        {
            Collect(child);
        }
    }

    private static bool DisplayNone(IElement element) => InlineStyle(element, "display") == "none";

    // The value of a property in the inline style attribute (last declaration wins), lower case, or null.
    private static string? InlineStyle(IElement element, string name)
    {
        var style = element.GetAttribute("style");
        if (string.IsNullOrEmpty(style))
        {
            return null;
        }

        string? result = null;

        foreach (var declaration in style.Split(';'))
        {
            var parts = declaration.Split(':', 2);
            if (parts.Length != 2)
            {
                continue;
            }

            if (string.Equals(parts[0].Trim(), name, StringComparison.OrdinalIgnoreCase))
            {
                result = parts[1].Replace("!important", string.Empty, StringComparison.OrdinalIgnoreCase).Trim().ToLowerInvariant();
            }
        }

        return result;
    }

    private static string? Lower(string? value) => value?.Trim().ToLowerInvariant();

    internal static IEnumerable<string> Tokens(string? value) =>
        string.IsNullOrWhiteSpace(value) ? [] : value.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries);

    internal static string Normalize(string? text) => RazorMarkupRules.Normalize(text);
}
